import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long[][] S = new long[5005][5005];
        long mod = 998244353;
        S[1][1] = 1;
        S[0][0] = 0;
        for (int i = 1; i <= 5000; i++) {
            S[i][i] = 1;
            S[i][0] = 0;
        }
        for (int i = 2; i <= 5000; i++) {
            for (int j = 1; j <= i; j++) {
                S[i][j] = (S[i - 1][j] * j % mod + S[i - 1][j - 1]) % mod;
            }
        }
        long n = sc.nextLong();
        long m = sc.nextLong();
        int k = sc.nextInt();
        m = powInverse(m, mod);
        long[] dp = new long[5005];
        dp[0] = 1;
        for (int i = 1; i <= Math.min(n, k); i++) {
            dp[i] = (dp[i - 1] * (n - i + 1)) % mod;
        }
        long total = 0;
        for (int i = 1; i <= Math.min(n, k); i++) {
            total = (total + dp[i] * pow(m, i, mod) % mod * S[k][i] % mod) % mod;
        }
        System.out.println(total);
    }

    public static long pow(long base, long exp, long mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    public static long powInverse(long a, long m) {
        return pow(a, m - 2, m);
    }
}
